mapper.select:
select * from oa_attendance_shift
status = #{status}
order by shift_code, shift_id

mapper.update:
update oa_attendance_shift set status=#{status}, row_version=row_version+1,
  update_by=#{updateBy}, update_time=now()
where shift_id=#{shiftId} and row_version=#{rowVersion}

mapper.delete:
delete from oa_attendance_shift
where shift_id=#{shiftId} and status='DISABLED'
  and row_version=#{rowVersion}
  and not exists (
    select 1 from oa_attendance_schedule s
    where s.shift_id=#{shiftId}
  )

mapper.select:
select s.*, d.dept_name shop_name from oa_attendance_site s
left join sys_dept d on d.dept_id=s.shop_id

    and s.shop_id=#{shopId}
    and s.status=#{status}

        and s.shop_id in
        #{id}


order by s.shop_id, s.site_code

mapper.update:
update oa_attendance_site set site_code=#{siteCode},site_name=#{siteName},
  address=#{address},longitude=#{longitude},latitude=#{latitude},
  coordinate_system=#{coordinateSystem},radius_meters=#{radiusMeters},
  max_accuracy_meters=#{maxAccuracyMeters},row_version=row_version+1,
  update_by=#{updateBy},update_time=now(),remark=#{remark}
where site_id=#{siteId} and shop_id=#{shopId} and row_version=#{rowVersion}

update oa_attendance_site set status=#{status},row_version=row_version+1,
  update_by=#{updateBy},update_time=now()
where site_id=#{siteId} and row_version=#{rowVersion}

mapper.delete:
delete from oa_attendance_site
where site_id=#{siteId} and shop_id=#{shopId} and status='DISABLED'
  and row_version=#{rowVersion}
  and not exists (
    select 1 from oa_attendance_schedule s
    where s.site_id=#{siteId}
  )

mapper.select:
select  

  and s.shop_id=#{shopId}
  and s.business_date >= #{dateFrom}
  and s.business_date <= #{dateTo}
  and s.user_id=#{userId}

    and s.shop_id in #{id}


order by s.business_date,s.user_name,s.schedule_id

mapper.delete:
delete from oa_attendance_schedule
where schedule_id=#{scheduleId} and shop_id=#{shopId}
  and status='DRAFT' and row_version=#{rowVersion}

mapper.update:
update oa_attendance_punch_challenge
set status='CONSUMED',consumed_at=#{consumedAt},consumed_event_id=#{eventId},row_version=row_version+1
where challenge_id=#{challengeId} and row_version=#{rowVersion}
  and status='ISSUED' and consumed_at is null and expires_at >= #{consumedAt}

mapper.select:
select e.evidence_id
from oa_attendance_evidence e
join oa_attendance_punch_event p on p.punch_event_id=e.punch_event_id
where e.punch_event_id=#{punchEventId}
  and p.schedule_id=#{scheduleId}
  and p.user_id=#{userId}
  and p.verification_status='ACCEPTED'
limit 1

select * from oa_attendance_remaining_work_confirmation
where schedule_id=#{scheduleId}
 and remaining_start=#{remainingStart} and remaining_end=#{remainingEnd}
order by confirmation_id desc limit 1
for update

select * from oa_attendance_remaining_work_confirmation
where schedule_id=#{scheduleId}
order by remaining_start,remaining_end,confirmation_id
